function alter_box(e){var t=e.currentTarget.id;var c=parseInt(t.split("")[1]);var a=e.key;if(a==="Backspace"||a==="Delete"){if(c!=1){var s="o"+(c-1).toString();document.getElementById(s).focus()}}else{if(c!=5){var n="o"+(c+1).toString();document.getElementById(n).focus()}}checkEmpty(e)}function checkEmpty(e){const t=e.currentTarget.closest(".group");const c=t.querySelectorAll(".otp-input");c.forEach((e=>{if(e.value)e.classList.remove("empty");else e.classList.add("empty")}))}function verifyOTP(){var e=document.getElementById("o1").value;var t=document.getElementById("o2").value;var c=document.getElementById("o3").value;var a=document.getElementById("o4").value;var s=document.getElementById("o5").value;var n=document.getElementById("alert_box");if(e!=""&&t!=""&&c!=""&&a!=""&&s!=""){var o=parseInt(e+t+c+a+s);n.style.display="none";alert(o)}else{n.style.display="block"}}function countdown(e,t,c){const a=document.querySelector(t);const s=a.parentNode;const n=document.querySelector(c);let o=e;if(!s.classList.contains("active"))s.classList.add("active");if(n.classList.contains("active"))n.classList.remove("active");const l=setInterval((()=>{a.innerText=o+"s";if(o===0){if(s.classList.contains("active"))s.classList.remove("active");if(!n.classList.contains("active"))n.classList.add("active");clearInterval(l)}o--}),1e3)}